document.querySelector('#full-view').onclick=()=>{full=true;render();};document.querySelector('#week-view').onclick=()=>{full=false;render();};
function report(make){document.querySelector('#report').style.display='block';document.querySelector('#report-title').textContent='제'+week+'주 주간 공사 보고서'+(make?' 초안':'');document.querySelector('#report-observation').textContent=week===7?'벽체 보드 설치 · 왼쪽 벽 78.50%, 오른쪽 벽 82.00% 관측. 이번 주 시작 작업이므로 지난주 내용은 생략합니다.':'선택한 제'+week+'주의 간트 항목에 대해 제출 사진과 진행 설명을 정리하는 시안입니다.';document.querySelector('#report-delay').textContent=week===7?'스프링클러 검사의 기존 종료일은 02.20, 요청 종료일은 02.23입니다. 본사 검토 결과와 사유를 함께 기록합니다.':'해당 주차의 지연·이월·기간 요청과 검토 결과를 기록합니다.';const nextFrom=week*7,nextTo=nextFrom+6;document.querySelector('#report-next').innerHTML=tasks.filter(t=>idx(t.start)<=nextTo&&idx(t.finish)>=nextFrom).map(t=>'<li>'+t.name+'</li>').join('')||'<li>다음 주 예정 작업 없음</li>';if(make){document.querySelector('#report-label').textContent='제'+week+'주 보고서 초안 · 시안에서 생성됨';notify('시안: 선택 주차의 보고서 초안을 만들었습니다.');}}
